// The content files the app ships instead of asking the graph (src/data/content/, generated by
// scripts/content-snapshot/build.mjs from a --content-only export; refreshed by load-graph.mjs).
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { assertContentOnly, buildParts, buildRelatedWords, buildSnapshots, indexGraph, USER_LABELS } from "../scripts/content-snapshot/build.mjs";
import { isLocalUri } from "../scripts/load-graph.mjs";
import { partsFromFixture } from "./lib/partsContentFixture.mjs";

const shipped = (name) => JSON.parse(readFileSync(`src/data/content/${name}`, "utf8"));
const node = (id, labels, props = {}) => ({ elementId: id, labels, props: { id, ...props } });
const rel = (type, start, end, props = {}) => ({ elementId: `${type}:${start}:${end}`, type, start, end, props });

test("build refuses anything but a content-only export with no user data", () => {
  const base = { scope: "content-only", nodes: [node("calm", ["Emotion"])], relationships: [] };
  assert.doesNotThrow(() => assertContentOnly(base));
  assert.throws(() => assertContentOnly({ ...base, scope: "no-profile" }), /--content-only/);
  assert.throws(() => assertContentOnly({ ...base, scope: "all" }), /--content-only/);
  for (const label of USER_LABELS) {
    assert.throws(() => assertContentOnly({ ...base, nodes: [...base.nodes, node("x", [label])] }), /user-data/, label);
  }
  assert.throws(() => assertContentOnly({ ...base, relationships: [rel("RELATED_TO", "calm", "gone")] }), /doesn't contain/);
  assert.throws(() => buildSnapshots({ ...base, nodes: [node("u", ["CheckIn", "UserData", "LogRecord"])] }), /user-data/);
});

test("related words keep RELATED_TO and shared-brain rows, never OPPOSITE_OF", () => {
  const nodes = [
    node("calm", ["Emotion"], { name: "Calm", quadrant: "low-pleasant" }),
    node("happy", ["Emotion"], { name: "Happy", quadrant: "high-pleasant" }),
    node("sad", ["Emotion"], { name: "Sad", quadrant: "low-unpleasant" }),
    node("tired", ["Emotion"], { name: "Tired", quadrant: "low-unpleasant" }),
    node("insula", ["BrainStructure"]),
  ];
  const relationships = [
    rel("RELATED_TO", "happy", "calm"),
    rel("OPPOSITE_OF", "calm", "sad"),
    rel("ACTIVATES_DURING", "insula", "calm"),
    rel("ACTIVATES_DURING", "insula", "tired"),
  ];
  const byId = new Map(nodes.map((n) => [n.elementId, n]));
  const g = {
    nodes: (l) => nodes.filter((n) => n.labels.includes(l)),
    rels: (t, a, b) => relationships.filter((r) => r.type === t)
      .map((r) => ({ props: r.props, a: byId.get(r.start), b: byId.get(r.end) }))
      .filter((r) => (!a || r.a.labels.includes(a)) && (!b || r.b.labels.includes(b))),
  };
  const out = buildRelatedWords(g);
  assert.deepEqual(out.calm.map((r) => [r.id, r.reason]), [["happy", "related feeling"], ["tired", "related feeling"]]);
  assert.equal(out.calm[0].quadrant, "high-pleasant");
  assert.ok(!JSON.stringify(out).includes("opposite"));
});

test("shipped files carry their source, and related words has no opposites and covers every grid word", () => {
  for (const name of ["related-words.json", "body-map.json", "find-the-feeling.json", "discriminating-questions.json", "capacity.json", "spine.json", "parts.json"]) {
    const f = shipped(name);
    assert.match(f.source.file, /^graph-content-only-.*\.json$/, name);
    assert.ok(!Number.isNaN(Date.parse(f.source.exportedAt)), name);
    assert.ok(f.content, name);
  }
  const related = shipped("related-words.json").content;
  for (const [id, rows] of Object.entries(related)) {
    for (const r of rows) assert.notEqual(r.reason, "opposite emotion", `${id} → ${r.id}`);
  }
  const grid = [...readFileSync("src/data/emotions.ts", "utf8").matchAll(/makeEmotion\('([a-z_]+)'/g)].map((m) => m[1]);
  const missing = grid.filter((id) => !related[id]?.length);
  assert.deepEqual(missing, [], "grid words with nothing in the graph to relate them to");
});

// Drift guards: the shipped files (from the live graph) against the fixtures (from content.py).
// A failure here means content.py changed without a graph load: load it, and load-graph.mjs
// refreshes src/data/content/ (or run `npm run content:refresh`).
test("shipped Find the feeling content matches content.py", () => {
  assert.deepEqual(shipped("find-the-feeling.json").content, JSON.parse(readFileSync("tests/fixtures/find-the-feeling-content.json", "utf8")));
});

test("shipped body map content matches content.py", () => {
  const snap = shipped("body-map.json").content;
  const fix = JSON.parse(readFileSync("tests/fixtures/body-map-content.json", "utf8"));
  const strip = (o, keys) => Object.fromEntries(Object.entries(o).filter(([k]) => !keys.includes(k)));
  assert.equal(snap.version, fix.version);
  assert.deepEqual(snap.regions, fix.regions);
  assert.deepEqual(snap.padWords, fix.padWords.filter((p) => (p.status ?? "live") === "live").map((p) => strip(p, ["status"])));
  const live = fix.maps.filter((m) => (m.status ?? "live") === "live");
  assert.deepEqual(snap.maps.map((m) => m.id).sort(), live.map((m) => m.id).sort());
  for (const m of snap.maps) {
    const f = live.find((x) => x.id === m.id);
    assert.equal(m.label, f.label, m.id);
    assert.deepEqual(m.wordIds, f.wordIds, m.id);
    assert.deepEqual(m.places, f.places.filter((p) => (p.status ?? "live") === "live").map((p) => strip(p, ["status", "emotionIds"])), m.id);
  }
});

test("shipped follow-up questions: both unpleasant quadrants, no clinical notes, follow-ups resolve, match the schema", () => {
  const shippedQs = shipped("discriminating-questions.json").content;
  const fixture = JSON.parse(readFileSync("tests/fixtures/recommendation-graph.json", "utf8"));
  // The check-in asks them for both unpleasant quadrants (CheckIn.tsx asksDiscriminatingQuestions).
  for (const q of ["high-unpleasant", "low-unpleasant"]) assert.ok(shippedQs[q]?.length > 0, q);
  // Only what getDiscriminatingQuestions returns: never the rationale, citations or signals.
  const text = JSON.stringify(shippedQs);
  for (const field of ["clinicalRationale", "keyCitations", "clinicalSignal", "clinicalDimension"]) assert.ok(!text.includes(field), field);
  for (const [quadrant, qs] of Object.entries(shippedQs)) {
    const ids = new Set(qs.map((q) => q.id));
    for (const q of qs) {
      assert.ok(q.text && q.responses.length > 0, q.id);
      for (const r of q.responses) if (r.triggersNextQuestionId) assert.ok(ids.has(r.triggersNextQuestionId), `${q.id} → ${r.triggersNextQuestionId}`);
    }
    // Drift guard: the same questions, in the same order, as the schema files say.
    assert.deepEqual(qs.map((q) => q.id), fixture.questions[quadrant] ?? [], quadrant);
  }
  // Every answer the engine scores (EVIDENCE_FOR) is one the app can send.
  const responseIds = new Set(Object.values(shippedQs).flat().flatMap((q) => q.responses.map((r) => r.id)));
  const scored = [...new Set(fixture.evidence.map((e) => e.responseId))];
  assert.deepEqual(scored.filter((id) => !responseIds.has(id)), []);
});

test("shipped capacity content matches content.py", () => {
  assert.deepEqual(shipped("capacity.json").content, JSON.parse(readFileSync("tests/fixtures/capacity-content.json", "utf8")));
});

test("shipped spine content: the close flow, and every non-reserved follow-up type the schema defines", () => {
  const spine = shipped("spine.json").content;
  assert.ok(spine.closeFlow?.kinds && spine.closeFlow.skip && spine.closeFlow.saved);
  assert.ok(!("version" in spine.closeFlow), "the flow's own version is stripped, as getSpineContent does");
  const schema = readFileSync("schema/practice-spine.cypher", "utf8");
  const types = [...schema.matchAll(/MERGE \(t:FollowUpType \{id: "([a-z_]+)"\}\)\nSET [^\n]*t\.reserved = (true|false)/g)];
  assert.ok(types.length >= 10, `${types.length} follow-up types read from the schema (guards the regex)`);
  const defined = [...new Set(types.filter(([, , r]) => r === "false").map(([, id]) => id))].sort();
  assert.deepEqual(spine.followUpTypes.map((t) => t.id), defined);
  for (const t of spine.followUpTypes) assert.equal(typeof t.enabled, "boolean", t.id);
});

test("shipped parts content is content.py's signed-off rows, and nothing a screen doesn't show", () => {
  const parts = shipped("parts.json").content;
  assert.deepEqual(parts, partsFromFixture(JSON.parse(readFileSync("tests/fixtures/parts-content.json", "utf8"))));
  // Trail rules, contexts and the policy stay on the server; pairs and keepsake wait for Two pulls.
  assert.deepEqual(Object.keys(parts).sort(), ["canTouch", "hurts", "moves", "options", "prompts", "version"]);
  assert.doesNotMatch(JSON.stringify(parts), /"(reviewStatus|pending)"/);
  // Every node parts.cypher writes as a draft (content.py's SIGNED_OFF doesn't list it), by label.
  const drafts = [...readFileSync("schema/parts.cypher", "utf8").matchAll(/^MERGE \(\w:(\w+) \{id: "([^"]+)"\}\)\nSET [^\n]*reviewStatus: "draft"/gm)];
  assert.ok(drafts.length > 100, `${drafts.length} drafts read from schema/parts.cypher (guards the regex)`);
  const draft = new Set(drafts.map(([, , id]) => id));
  // No draft row ships, and no shipped row is guarded by a draft move (OFTEN_GUARDS is reviewed by its move).
  // An option's `moves` may name a move not yet signed off, as an option may ship before its prompt: the
  // client's flowReady decides what is complete.
  const shippedIds = [
    ...parts.moves.map((m) => m.id), ...Object.keys(parts.prompts),
    ...Object.values(parts.options).flatMap((steps) => Object.values(steps).flat().map((o) => o.id)),
    ...parts.hurts.flatMap((h) => [h.id, ...h.guardedBy.map((g) => g.moveId)]),
    ...Object.values(parts.canTouch).flat(),
  ];
  assert.deepEqual(shippedIds.filter((id) => draft.has(id)), [], "draft parts content in the app bundle");
});

test("buildParts: signed-off rows only, any content property carried, edges by their source's review", () => {
  const ok = { reviewStatus: "approved", version: "parts-v1" };
  const draft = { reviewStatus: "draft", version: "parts-v1" };
  const nodes = [
    node("hide", ["ProtectiveMove"], { ...ok, label: "Hide", offerable: true, safetyLine: false, order: 2, newField: "kept" }),
    node("chase", ["ProtectiveMove"], { ...draft, label: "Chase", offerable: true, order: 1 }),
    node("go_blank", ["ProtectiveMove"], { ...ok, label: "Go blank", offerable: false, order: 3 }),
    node("meet_find", ["PartPrompt"], { ...ok, flow: "meet", step: "find", order: 0, copy: "What's showing up?" }),
    node("meet_where", ["PartPrompt"], { ...draft, flow: "meet", step: "where", order: 1, copy: "Where?" }),
    node("gate_wait", ["PartPrompt"], { ...ok, pending: "a decision", flow: "gate", step: "x", order: 0, copy: "Waiting" }),
    node("keepsake_x", ["PartPrompt"], { ...ok, flow: "pulls", step: "keepsake", order: 6, copy: "{A} and {B}", copyKind: "keepsake" }),
    node("voice_b", ["PartOption"], { ...ok, flow: "meet", step: "voice", order: 1, label: "B", kind: "voice", branch: "continue" }),
    node("voice_a", ["PartOption"], { ...ok, flow: "meet", step: "voice", order: 0, label: "A", kind: "chip", flag: "tender", selfLike: false, branch: "conservative" }),
    node("voice_c", ["PartOption"], { ...draft, flow: "meet", step: "voice", order: 2, label: "C", kind: "chip", branch: "continue" }),
    node("brushed_off", ["ProtectedHurt"], { ...ok, label: "being brushed off", order: 0, matters: "being taken seriously" }),
    node("left_out", ["ProtectedHurt"], { ...draft, label: "being left out", order: 1 }),
    node("made_small", ["ProtectedHurt"], { ...ok, label: "being made small", order: 2, matters: "being treated as an equal" }),
    node("hurt", ["Emotion"]), node("disrespected", ["Emotion"]),
    // Recover's events carry no review of their own: CAN_TOUCH is reviewed on the edge.
    node("dismissed", ["InvalidationEvent"]), node("ignored", ["InvalidationEvent"]), node("mocked", ["InvalidationEvent"]),
    node("tp_agree", ["ThoughtPattern"]),
    node("parts", ["PartsPolicy"], { ...draft, offersEnabled: false, floodGateHours: 2 }),
  ];
  const relationships = [
    rel("OFFERED_FOR", "voice_a", "chase", { reviewStatus: "approved", order: 1 }),
    rel("OFFERED_FOR", "voice_a", "hide", { reviewStatus: "approved", order: 0 }),
    rel("OFFERED_FOR", "voice_c", "hide", { reviewStatus: "draft", order: 0 }),
    rel("SAME_AS", "voice_b", "tp_agree", { reviewStatus: "approved" }),
    rel("NAMED_AS", "brushed_off", "hurt", { reviewStatus: "approved" }),
    rel("NAMED_AS", "brushed_off", "disrespected", { reviewStatus: "approved" }),
    rel("OFTEN_GUARDS", "hide", "brushed_off", { reviewStatus: "approved", rank: 1 }),
    rel("OFTEN_GUARDS", "chase", "brushed_off", { reviewStatus: "draft", rank: 0 }),
    // In the edge's order, not the hurts'; a draft hurt or a draft edge drops out; an event left with none is absent.
    rel("CAN_TOUCH", "dismissed", "made_small", { reviewStatus: "approved", order: 0 }),
    rel("CAN_TOUCH", "dismissed", "left_out", { reviewStatus: "approved", order: 1 }),
    rel("CAN_TOUCH", "dismissed", "brushed_off", { reviewStatus: "approved", order: 2 }),
    rel("CAN_TOUCH", "ignored", "brushed_off", { reviewStatus: "draft", order: 0 }),
    rel("CAN_TOUCH", "mocked", "brushed_off", { reviewStatus: "approved", pending: "a decision", order: 0 }),
    rel("CAN_TOUCH", "mocked", "left_out", { reviewStatus: "approved", order: 1 }),
  ];
  const exp = { scope: "content-only", nodes, relationships };
  assertContentOnly(exp);
  assert.deepEqual(buildParts(indexGraph(exp)), {
    version: "parts-v1",
    moves: [{ id: "hide", label: "Hide", safetyLine: false, order: 2, newField: "kept" }],
    prompts: { meet_find: { flow: "meet", step: "find", order: 0, copy: "What's showing up?" } },
    options: {
      meet: {
        voice: [
          { id: "voice_a", label: "A", kind: "chip", flag: "tender", selfLike: false, branch: "conservative", order: 0, moves: ["hide", "chase"], sameAs: [] },
          { id: "voice_b", label: "B", kind: "voice", flag: null, selfLike: null, branch: "continue", order: 1, moves: [], sameAs: [{ label: "ThoughtPattern", id: "tp_agree" }] },
        ],
      },
    },
    hurts: [{
      id: "brushed_off", label: "being brushed off", order: 0, matters: "being taken seriously",
      namedAs: ["disrespected", "hurt"], guardedBy: [{ moveId: "hide", rank: 1 }],
    }, { id: "made_small", label: "being made small", order: 2, matters: "being treated as an equal", namedAs: [], guardedBy: [] }],
    canTouch: { dismissed: ["made_small", "brushed_off"] },
  });
  // Nothing signed off: an empty file carrying the version every parts node has (the policy's), or none at all.
  const none = { scope: "content-only", nodes: nodes.map((n) => (n.labels.includes("PartsPolicy") ? n : { ...n, props: { ...n.props, reviewStatus: "draft" } })), relationships: [] };
  assert.deepEqual(buildParts(indexGraph(none)), { version: "parts-v1", moves: [], prompts: {}, options: {}, hurts: [], canTouch: {} });
  assert.equal(buildParts(indexGraph({ scope: "content-only", nodes: [], relationships: [] })).version, null);
  // The policy's two client numbers ship once it is signed off; nothing else of it ever does.
  const signedPolicy = { ...exp, nodes: nodes.map((n) => (n.labels.includes("PartsPolicy")
    ? { ...n, props: { ...n.props, ...ok, nameMaxChars: 40, maxNonSelfAnswers: 2, tooManyPartsCount: 3 } } : n)) };
  const withLimits = buildParts(indexGraph(signedPolicy));
  assert.deepEqual(withLimits.limits, { nameMaxChars: 40, maxNonSelfAnswers: 2 });
  assert.doesNotMatch(JSON.stringify(withLimits), /offersEnabled|floodGateHours|tooManyPartsCount/);
  assert.ok(!("limits" in buildParts(indexGraph(exp))), "a draft policy: no limits key");
  const mixed = { ...exp, nodes: nodes.map((n) => (n.props.id === "voice_b" ? { ...n, props: { ...n.props, version: "parts-v2" } } : n)) };
  assert.throws(() => buildParts(indexGraph(mixed)), /mixes versions/);
});

test("load-graph never refreshes the shipped files from a local graph", () => {
  for (const u of ["bolt://127.0.0.1:7687", "neo4j://localhost", "neo4j://localhost:7687", "bolt://[::1]:7687"]) assert.ok(isLocalUri(u), u);
  for (const u of ["neo4j+s://abcd.databases.neo4j.io", "neo4j+s://localhost.example.io", "", undefined]) assert.ok(!isLocalUri(u), String(u));
});
